import{_ as n,c as t,o as i,ah as r}from"./chunks/framework.dGCgOE9J.js";const d="/Qonnectra-docs/pr-27/images/manual/teil-b/permission_users.jpg",s="/Qonnectra-docs/pr-27/images/manual/teil-b/permission_user_form.jpg",a="/Qonnectra-docs/pr-27/images/manual/teil-b/permission_model_list.jpg",o="/Qonnectra-docs/pr-27/images/manual/teil-b/permission_route_list.jpg",l="/Qonnectra-docs/pr-27/images/manual/teil-b/permission_group_form.jpg",u="/Qonnectra-docs/pr-27/images/manual/teil-b/permission_model_add.jpg",S=JSON.parse('{"title":"19. Rollen und Rechte","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/19-rollen-und-rechte.md","filePath":"manual/teil-b-betrieb-admin-qgis/19-rollen-und-rechte.md"}'),c={name:"manual/teil-b-betrieb-admin-qgis/19-rollen-und-rechte.md"};function h(p,e,b,g,m,f){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_19-rollen-und-rechte" tabindex="-1">19. Rollen und Rechte <a class="header-anchor" href="#_19-rollen-und-rechte" aria-label="Permalink to &quot;19. Rollen und Rechte&quot;">​</a></h1><p>Was ein Konto in Qonnectra sehen und ändern darf, legen Sie im Administrationsbereich fest. Dieses Kapitel beschreibt, aus welchen Teilen sich die Rechte eines Kontos zusammensetzen, wie Sie Konten und Gruppen anlegen und welche Rollen Qonnectra mitbringt. Wie Sie den Administrationsbereich erreichen und bedienen, beschreibt Kapitel <a href="./20-administrationsbereich.html">Der Administrationsbereich</a>.</p><p><img src="'+d+'" alt="Screenshot der Benutzerliste im Administrationsbereich mit drei Konten in den Gruppen „Admin“, „Editor“ und „Viewer“" data-zoomable="true"></p><p>Die Rechte eines Kontos ergeben sich aus drei voneinander unabhängigen Einstellungen:</p><ul><li><strong>Gruppenmitgliedschaft</strong> – die Gruppe bestimmt, was das Konto in der Weboberfläche darf: welche Objektarten es ansehen, bearbeiten und löschen kann (<strong>Modellrechte</strong>, Abschnitt <a href="#_19-2-modellrechte-zugriff-je-datenmodell">Modellrechte</a>) und welche Menüpunkte es öffnen darf (<strong>Routenrechte</strong>, Abschnitt <a href="#_19-3-routenrechte-zugriff-je-menupunkt">Routenrechte</a>).</li><li><strong>„Mitarbeiter-Status“</strong> – erlaubt die Anmeldung im Administrationsbereich und, zusammen mit dem passenden Routenrecht, das Lesen der Systemprotokolle („Logs“) in der Weboberfläche.</li><li><strong>„Administrator-Status“</strong> – macht das Konto zum <strong>Superuser</strong>, der jede Prüfung umgeht, siehe Abschnitt <a href="#_19-4-superuser-gegenuber-gruppenmitgliedschaft">Superuser gegenüber Gruppenmitgliedschaft</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Benutzerliste zeigt als Spalte nur den „Mitarbeiter-Status“, nicht den „Administrator-Status“. Welche Konten Superuser sind, sehen Sie über den Filter „Nach Administrator-Status“ rechts neben der Liste oder im Formular des Kontos.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Gruppe „Admin“ und der Administrationsbereich haben nichts miteinander zu tun, siehe Abschnitt <a href="#_19-4-superuser-gegenuber-gruppenmitgliedschaft">Superuser gegenüber Gruppenmitgliedschaft</a>.</p></div><h2 id="_19-1-benutzende-und-gruppen-anlegen" tabindex="-1">19.1 Benutzende und Gruppen anlegen <a class="header-anchor" href="#_19-1-benutzende-und-gruppen-anlegen" aria-label="Permalink to &quot;19.1 Benutzende und Gruppen anlegen&quot;">​</a></h2><p>Konten pflegen Sie unter „Authentifizierung und Autorisierung“ → „Benutzer“. Eine Selbstregistrierung gibt es nicht, und die Weboberfläche kann weder Konten anlegen noch Passwörter zurücksetzen.</p><ol><li>Klicken Sie in der Benutzerliste oben rechts auf „Benutzer hinzufügen“.</li><li>Geben Sie unter „Benutzername“ einen Namen und zweimal das Passwort ein und klicken Sie auf „Sichern und weiter bearbeiten“.</li><li>Tragen Sie im folgenden Formular unter „Persönliche Informationen“ Vor- und Nachnamen und die E-Mail-Adresse ein.</li><li>Wählen Sie unter „Berechtigungen“ im Feld „Gruppen“ die Gruppe aus, siehe Abschnitt <a href="#_19-5-typische-rollenprofile-betrachten-bearbeiten-verwalten">Typische Rollenprofile</a>.</li><li>Klicken Sie auf „Sichern“.</li></ol><p><img src="'+s+'" alt="Screenshot des Benutzerformulars im Administrationsbereich mit Hervorhebung der drei Status-Felder und der Gruppen unten im Abschnitt „Berechtigungen“" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein Konto ohne Gruppe kann sich anmelden und sieht alle Menüpunkte, aber keine Daten: Ohne Gruppe hat es auf keine Objektart ein Recht, und jede Ansicht scheitert beim Laden. Wählen Sie die Gruppe deshalb gleich beim Anlegen.</p></div><p>Gehört ein Konto mehreren Gruppen an, gilt je Objektart die höchste Stufe, die eine seiner Gruppen vergibt. Ein Konto in „Viewer“ und „Editor“ darf also bearbeiten.</p><p>Ein Konto, das nicht mehr arbeiten soll, deaktivieren Sie, statt es zu löschen: Entfernen Sie den Haken bei „Aktiv“. Die Anmeldung schlägt dann fehl, Einträge im Protokoll und im Änderungsverlauf behalten aber ihren Bezug zu dem Konto.</p><p>Das Passwort eines Kontos setzen Sie im Benutzerformular über den Link unter dem Feld „Passwort“ neu. Das alte Passwort lässt sich nicht einsehen; Qonnectra speichert nur einen daraus berechneten Wert.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein geändertes Passwort beendet laufende Sitzungen der Weboberfläche nicht sofort. Die Anmeldung dort hält bis zu sieben Tage und verlängert sich, solange das Konto aktiv bleibt. Wollen Sie ein Konto sofort sperren, deaktivieren Sie es.</p></div><p>Gruppen pflegen Sie unter „Authentifizierung und Autorisierung“ → „Gruppen“. Eine neue Gruppe hat zunächst keine Rechte; sie erhält sie erst über die Modell- und Routenrechte der folgenden Abschnitte.</p><h2 id="_19-2-modellrechte-zugriff-je-datenmodell" tabindex="-1">19.2 Modellrechte: Zugriff je Datenmodell <a class="header-anchor" href="#_19-2-modellrechte-zugriff-je-datenmodell" aria-label="Permalink to &quot;19.2 Modellrechte: Zugriff je Datenmodell&quot;">​</a></h2><p>Die <strong>Modellrechte</strong> legen je Gruppe und Objektart fest, was ein Konto mit den Daten tun darf. Sie stehen unter „Api“ → „Modell-Zugriffsrechte“, eine Zeile je Gruppe und Objektart.</p><p><img src="'+a+'" alt="Screenshot der Modell-Zugriffsrechte, gefiltert auf die Gruppe „Editor“, mit Hervorhebung der Filterleiste rechts und der Spalte „Zugriffsebene“" data-zoomable="true"></p><p>Jede Zeile hat eine von vier Zugriffsebenen:</p><ul><li>„Kein Zugriff“ – die Objektart bleibt verborgen; jede Anfrage scheitert.</li><li>„Nur Ansehen“ – lesen.</li><li>„Ansehen und Bearbeiten“ – lesen, anlegen und ändern, aber nicht löschen.</li><li>„Vollzugriff“ – zusätzlich löschen.</li></ul><p>Die Spalte „Zugriffsebene“ lässt sich direkt in der Liste ändern, siehe Abschnitt <a href="./20-administrationsbereich.html#_20-2-suchen-filtern-und-massenbearbeitung">Suchen, Filtern und Massenbearbeitung</a>. Fehlt für eine Objektart die Zeile, gilt „Kein Zugriff“.</p><p>Die Objektarten stehen in der Spalte „Modellname“ mit ihrem technischen Namen. Wirksam sind diese Zeilen:</p><table tabindex="0"><thead><tr><th>Modellname</th><th>Bereich der Weboberfläche</th></tr></thead><tbody><tr><td><code>trench</code>, <code>conduit</code>, <code>microduct</code></td><td>Trassen, Rohre und Mikrorohre</td></tr><tr><td><code>trenchconduitconnection</code>, <code>trenchconduitcanvas</code></td><td>Rohrzuordnung und Grabenprofil</td></tr><tr><td><code>microductconnection</code></td><td>Verbindungen der Mikrorohre in der Rohrverzweigung</td></tr><tr><td><code>node</code>, <code>address</code>, <code>residentialunit</code>, <code>area</code></td><td>Netzknoten, Adressen, Wohneinheiten, Gebiete</td></tr><tr><td><code>cable</code>, <code>fiber</code>, <code>fibersplice</code>, <code>cablelabel</code></td><td>Kabel, Fasern, Spleiße und Kabelbeschriftungen im Netzschema</td></tr><tr><td><code>microductcableconnection</code></td><td>Verknüpfung von Kabeln mit Mikrorohren, soweit sie einzeln bearbeitet wird</td></tr><tr><td><code>nodeslotconfiguration</code>, <code>nodestructure</code>, <code>container</code></td><td>Aufbau eines Netzknotens</td></tr><tr><td><code>pipelinerecord</code>, <code>pipelineinquiryarea</code></td><td>Auskünfte und Auskunftsbereiche der Leitungsauskunft</td></tr><tr><td><code>featurefiles</code></td><td>Anhänge</td></tr><tr><td><code>wmslayer</code></td><td>die einzelnen Layer externer Kartendienste; die Dienste selbst (<code>wmssource</code>) siehe Abschnitt <a href="#_19-6-rechte-die-keine-mitgelieferte-rolle-enthalt">Rechte, die keine mitgelieferte Rolle enthält</a></td></tr></tbody></table><p>Sieben weitere Zeilen bringt Qonnectra mit, sie wirken aber nicht: <code>projects</code>, <code>flags</code>, <code>containertype</code>, <code>typeofwork</code>, <code>requestreason</code>, <code>qgisproject</code> und <code>logentry</code>. Projekte, Kennzeichen, Container-Typen und die Auswahllisten der Leitungsauskunft sind wie alle übrigen Stammdaten – Status, Rohrtypen, Firmen – für jedes angemeldete Konto lesbar und lassen sich nur im Administrationsbereich ändern. Wer die Systemprotokolle lesen darf, regeln „Mitarbeiter-Status“ und Routenrecht, siehe Abschnitt <a href="#_19-4-superuser-gegenuber-gruppenmitgliedschaft">Superuser gegenüber Gruppenmitgliedschaft</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Eine geänderte Zugriffsebene greift nicht sofort. Qonnectra hält die Rechte eines Kontos bis zu fünf Minuten zwischengespeichert. Die Navigationsleiste zeigt die neuen Rechte zwar beim nächsten Seitenaufruf, eine Aktion kann in dieser Zeit aber noch mit dem alten Recht gelingen oder scheitern.</p></div><h2 id="_19-3-routenrechte-zugriff-je-menupunkt" tabindex="-1">19.3 Routenrechte: Zugriff je Menüpunkt <a class="header-anchor" href="#_19-3-routenrechte-zugriff-je-menupunkt" aria-label="Permalink to &quot;19.3 Routenrechte: Zugriff je Menüpunkt&quot;">​</a></h2><p>Die <strong>Routenrechte</strong> blenden Menüpunkte der Weboberfläche für eine Gruppe aus. Sie stehen unter „Api“ → „Seiten-Zugriffsrechte“. Jede Zeile nennt eine Gruppe, ein „Route-Muster“ und ob es „Erlaubt“ ist.</p><p><img src="'+o+'" alt="Screenshot der Seiten-Zugriffsrechte mit den drei mitgelieferten Zeilen für das Muster „/admin/*“ in der Mitte" data-zoomable="true"></p><p>Mitgeliefert ist für jede der drei Gruppen genau eine Zeile: Das Muster <code>/admin/*</code> ist für „Admin“ erlaubt und für „Editor“ und „Viewer“ gesperrt. Es betrifft in der Weboberfläche nur einen Menüpunkt, die „Logs“ am Fuß der Navigationsleiste. Alles, wofür keine Zeile existiert, ist erlaubt.</p><p>Das Muster ist entweder ein vollständiger Pfad oder ein Pfad mit <code>/*</code> am Ende, der alles darunter umfasst. Die Pfade der Menüpunkte:</p><table tabindex="0"><thead><tr><th>Menüpunkt</th><th>Pfad</th><th>Menüpunkt</th><th>Pfad</th></tr></thead><tbody><tr><td>„Dashboard“</td><td><code>/dashboard</code></td><td>„Verwaltung“ (Rohr)</td><td><code>/conduit</code></td></tr><tr><td>„Karte“</td><td><code>/map</code></td><td>„Zuordnung“ (Rohr)</td><td><code>/trench</code></td></tr><tr><td>„Störungsanalyse“</td><td><code>/fault-simulation</code></td><td>„Verzweigung“ (Rohr)</td><td><code>/pipe-branch</code></td></tr><tr><td>„Nachverdichtung“</td><td><code>/post-compaction</code></td><td>„Mikrorohre“</td><td><code>/house-connections</code></td></tr><tr><td>„Leitungsauskunft“</td><td><code>/pipeline-records</code></td><td>„Netzschema“</td><td><code>/network-schema</code></td></tr><tr><td>„Wertermittlung“</td><td><code>/valuation</code></td><td>„Faserweg“</td><td><code>/trace</code></td></tr><tr><td>„Adressen“</td><td><code>/address</code></td><td>„Einstellungen“</td><td><code>/settings</code></td></tr><tr><td>„Logs“</td><td><code>/admin/logs</code></td><td></td><td></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Um einen Menüpunkt zu sperren, brauchen Sie zwei Zeilen, etwa <code>/valuation</code> und <code>/valuation/*</code>. Die Ansichten hängen die Nummer des Projekts an den Pfad an (<code>/valuation/2</code>), und jedes Muster erfasst nur eine der beiden Formen. Mit <code>/valuation</code> allein verschwindet der Eintrag aus der Navigationsleiste, ein Lesezeichen auf die Ansicht öffnet sie aber weiterhin. Mit <code>/valuation/*</code> allein bleibt der Eintrag stehen und führt beim Klick ohne Meldung in die Karte, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/18-wenn-etwas-nicht-funktioniert.html#_18-3-fehlende-rechte-erkennen">Fehlende Rechte erkennen</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Routenrechte sind kein Schutz der Daten. Sie verbergen einen Menüpunkt, nicht die Daten dahinter: Dieselben Daten erscheinen in anderen Ansichten und sind über die Schnittstelle abrufbar. Was eine Gruppe nicht sehen darf, sperren Sie über die Modellrechte.</p></div><h2 id="_19-4-superuser-gegenuber-gruppenmitgliedschaft" tabindex="-1">19.4 Superuser gegenüber Gruppenmitgliedschaft <a class="header-anchor" href="#_19-4-superuser-gegenuber-gruppenmitgliedschaft" aria-label="Permalink to &quot;19.4 Superuser gegenüber Gruppenmitgliedschaft&quot;">​</a></h2><p>Ein Konto mit „Administrator-Status“ ist <strong>Superuser</strong>. Für ein solches Konto gelten weder Modell- noch Routenrechte: Es sieht jeden Menüpunkt, darf jede Objektart löschen und sieht auch die Daten, für die keine Gruppe ein Recht hat, etwa die externen Kartendienste. Seine Gruppenmitgliedschaft spielt keine Rolle.</p><p>Für den Administrationsbereich gilt anderes als für die Weboberfläche:</p><ul><li>Anmelden kann sich dort nur ein Konto mit „Mitarbeiter-Status“.</li><li>Bearbeiten kann es dort nur, was ihm das Feld „Berechtigungen“ im Gruppen- oder Benutzerformular erlaubt. Bei den mitgelieferten Gruppen ist dieses Feld leer.</li></ul><p><img src="'+l+'" alt="Screenshot des Formulars der Gruppe „Admin“ mit Hervorhebung des leeren Feldes „Berechtigungen“ unter dem Namen" data-zoomable="true"></p><p>In der Praxis ist der Administrationsbereich deshalb dem Superuser-Konto vorbehalten. Ein Konto, das nur „Mitarbeiter-Status“ hat, kommt zwar hinein, sieht dort aber statt der Bereiche nur die Meldung „Das Benutzerkonto besitzt nicht die nötigen Rechte, um etwas anzusehen oder zu ändern.“ Bei einem Konto ohne den Status scheitert schon die Anmeldung: „Bitte Benutzername und Passwort für einen Staff-Account eingeben.“</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Berechtigungen im Gruppen- und im Benutzerformular („Can add …“, „Can change …“) wirken nur im Administrationsbereich. Auf die Weboberfläche haben sie keinen Einfluss – dort zählen ausschließlich die Modell- und Routenrechte.</p></div><p>Die „Logs“ der Weboberfläche öffnen sich nur, wenn beides zutrifft: Das Konto hat „Mitarbeiter-Status“, und seine Gruppe darf den Pfad <code>/admin/*</code> öffnen – von den mitgelieferten Gruppen nur „Admin“. Die „Log-Einträge“ im Administrationsbereich sieht ohnehin nur das Superuser-Konto.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Fehlt eine der beiden Voraussetzungen, landet das Konto ohne Meldung in der Karte. Ein Mitglied der Gruppe „Admin“ ohne „Mitarbeiter-Status“ sieht den Menüpunkt „Logs“ sogar, kommt aber nicht auf die Seite.</p></div><p>Der erste Superuser entsteht bei der Einrichtung der Instanz aus der Konfiguration, siehe Abschnitt <a href="./28-betrieb-der-instanz.html#_28-2-konfiguration-uber-umgebungsvariablen">Konfiguration über Umgebungsvariablen</a>. Legen Sie für die tägliche Arbeit eigene Konten an und nutzen Sie den Superuser nur für die Verwaltung.</p><h2 id="_19-5-typische-rollenprofile-betrachten-bearbeiten-verwalten" tabindex="-1">19.5 Typische Rollenprofile: Betrachten, Bearbeiten, Verwalten <a class="header-anchor" href="#_19-5-typische-rollenprofile-betrachten-bearbeiten-verwalten" aria-label="Permalink to &quot;19.5 Typische Rollenprofile: Betrachten, Bearbeiten, Verwalten&quot;">​</a></h2><p>Qonnectra bringt drei Gruppen mit, die drei Rollen entsprechen:</p><table tabindex="0"><thead><tr><th>Gruppe</th><th>Fachdaten</th><th>Menüpunkt „Logs“</th><th>Typisch für</th></tr></thead><tbody><tr><td>„Viewer“</td><td>„Nur Ansehen“</td><td>ausgeblendet</td><td>Auskunft, Entscheidung, externe Stellen</td></tr><tr><td>„Editor“</td><td>„Ansehen und Bearbeiten“</td><td>ausgeblendet</td><td>Sachbearbeitung, Dokumentation</td></tr><tr><td>„Admin“</td><td>„Vollzugriff“</td><td>sichtbar, öffnet sich mit „Mitarbeiter-Status“</td><td>fachlich Verantwortliche, die auch löschen</td></tr></tbody></table><p>Der wichtigste Unterschied zwischen „Editor“ und „Admin“ ist das Löschen. Mit „Editor“ lässt sich in der Weboberfläche nichts entfernen – kein Rohr, kein Anhang, keine Slot-Konfiguration. „Ansehen und Bearbeiten“ umfasst dagegen das Anlegen: Rohre, Anhänge, Wohneinheiten und Auskünfte legt ein „Editor“ selbst an.</p><p>Die Weboberfläche zeigt jeder Rolle dieselben Schaltflächen. Ob eine Aktion erlaubt ist, entscheidet sich erst beim Speichern; scheitert sie, erscheint die Meldung aus Abschnitt <a href="./../teil-a-anwenderhandbuch/18-wenn-etwas-nicht-funktioniert.html#_18-3-fehlende-rechte-erkennen">Fehlende Rechte erkennen</a>. Weisen Sie Nutzende mit der Rolle „Viewer“ darauf hin.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>„Viewer“ ist nicht vollständig schreibgeschützt. Zwei Aktionen prüfen nur die Anmeldung und nicht die Modellrechte, sie gelingen deshalb mit jeder Rolle:</p><ul><li>der Excel-Import in der Rohrverwaltung, der Rohre samt Mikrorohren anlegt, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/10-rohrverwaltung.html#_10-5-excel-import-vorlage-ablauf-fehlermeldungen">Excel-Import</a>,</li><li>das Verknüpfen und Lösen von Kabeln und Mikrorohren im Netzschema, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/14-netzschema.html#_14-5-kabel-mit-mikrorohren-verknupfen">Kabel mit Mikrorohren verknüpfen</a>.</li></ul><p>Wer Daten auf keinen Fall ändern darf, bekommt kein Konto, sondern einen Export, siehe Kapitel <a href="./24-daten-import-und-export.html">Daten importieren und exportieren</a>.</p></div><p>Eine eigene Rolle legen Sie an, indem Sie eine Gruppe anlegen und für jede Objektart eine Zeile in den Modell-Zugriffsrechten hinzufügen, siehe Abschnitt <a href="#_19-6-rechte-die-keine-mitgelieferte-rolle-enthalt">Rechte, die keine mitgelieferte Rolle enthält</a>. Am schnellsten geht das, wenn Sie die Zeilen einer bestehenden Gruppe als Vorlage nehmen und die abweichenden Stufen ändern.</p><h2 id="_19-6-rechte-die-keine-mitgelieferte-rolle-enthalt" tabindex="-1">19.6 Rechte, die keine mitgelieferte Rolle enthält <a class="header-anchor" href="#_19-6-rechte-die-keine-mitgelieferte-rolle-enthalt" aria-label="Permalink to &quot;19.6 Rechte, die keine mitgelieferte Rolle enthält&quot;">​</a></h2><p>Für vier Objektarten bringt keine Gruppe eine Zeile mit. Ohne Zeile gilt „Kein Zugriff“, und zwar auch für die Gruppe „Admin“ – nur das Superuser-Konto sieht sie:</p><table tabindex="0"><thead><tr><th>Modellname</th><th>Was ohne das Recht fehlt</th></tr></thead><tbody><tr><td><code>wmssource</code></td><td>die externen Kartendienste in der Legende der Karte, siehe Abschnitt <a href="./27-qgis-server-und-kartendienste.html#_27-4-externe-wms-quellen-als-hintergrund-einbinden">Externe WMS-Quellen als Hintergrund einbinden</a></td></tr><tr><td><code>nodetrenchselection</code></td><td>das Speichern der „Grabenauswahl“ in der Rohrverzweigung; die Erfolgsmeldung erscheint trotzdem, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/12-rohrverzweigung.html">Rohrverzweigung</a></td></tr><tr><td><code>nodeslotclipnumber</code></td><td>Clip-Nummern in der Slot-Ansicht eines Netzknotens</td></tr><tr><td><code>nodeslotdivider</code></td><td>Trennlinien in der Slot-Ansicht eines Netzknotens</td></tr></tbody></table><p>Das Recht fügen Sie der Gruppe als neue Zeile hinzu:</p><ol><li>Öffnen Sie „Api“ → „Modell-Zugriffsrechte“ und klicken Sie oben rechts auf „Modell-Zugriffsrecht hinzufügen“.</li><li>Wählen Sie die „Gruppe“.</li><li>Tragen Sie unter „Modellname“ den Namen aus der Tabelle ein, kleingeschrieben und ohne Leerzeichen.</li><li>Wählen Sie die „Zugriffsebene“ und klicken Sie auf „Sichern“.</li></ol><p><img src="'+u+'" alt="Screenshot des Formulars „Modell-Zugriffsrecht hinzufügen“ mit der Gruppe „Viewer“, dem Modellnamen „wmssource“ und der Zugriffsebene „Nur Ansehen“ oben im Formular" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der „Modellname“ ist ein freies Textfeld. Ein Tippfehler legt eine Zeile an, die nichts bewirkt, ohne Fehlermeldung. Prüfen Sie das Ergebnis mit einem Konto der Gruppe in der Weboberfläche.</p></div>',59)])])}const z=n(c,[["render",h]]);export{S as __pageData,z as default};
